public final class ActivitySelectionHarness {
    private ActivitySelectionHarness() {
    }

    public static void main(String[] args) {
        int[] start = {1, 3, 0, 5, 8, 5};
        int[] finish = {2, 4, 6, 7, 9, 9};
        List<ActivitySelection.Activity> activities = List.of(
            new ActivitySelection.Activity(1, 2),
            new ActivitySelection.Activity(3, 4),
            new ActivitySelection.Activity(0, 6),
            new ActivitySelection.Activity(5, 7),
            new ActivitySelection.Activity(8, 9),
            new ActivitySelection.Activity(5, 9)
        );

        System.out.println(ActivitySelection.activitySelection(start, finish));
        System.out.println(ActivitySelection.activitySelection(activities));
        System.out.println(ActivitySelection.selectActivities(activities));
        System.out.println(ActivitySelection.optimalSchedule(activities));
    }
}

